void RousingSpeechUpdate::updateAt00265510()
{
	RousingSpeechUpdateModuleData *data = m_data;
	reinterpret_cast<Rva0025EF90Owner *>(this)->callAt002A9850();
	reinterpret_cast<Rva00265150Owner *>(this)->callAt00265150();
	if (m_ids.empty())
		return;

	std::vector<AsciiString> modifiers(data->m_modifierName);
	GameLogic *logic = TheBfmeGameLogic;
	for (std::vector<AsciiString>::const_iterator modifier = modifiers.begin();
		modifier != modifiers.end(); ++modifier)
	{
		for (_STL::list<ObjectID>::iterator id = m_ids.begin();
			id != m_ids.end(); ++id)
		{
			Object *object =
				logic->findObjectByID(*id);
