				setRousingCondition(object, 191);
				object->m_objectIdAt360 = m_object->m_id;
				FXList *fx = data->m_followerFX;
				if (fx != 0 && !fx->bfmeIsBlocked())
					fx->doFXObj(object, 0);
				logic = TheBfmeGameLogic;
			}
		}
	}

	if (data->m_levelUp)
	{
